def encode_shift(s: str):
    """
    Returns encoded string by shifting every character by 5 in the alphabet.
    Assumes the input consists of lowercase letters a-z.
    """
    return "".join(
        chr(((ord(ch) + 5 - ord("a")) % 26) + ord("a")) for ch in s
    )


def decode_shift(s: str):
    """
    Takes as input a string encoded with `encode_shift`. Returns the original string
    by shifting each character back by 5 positions in the alphabet.
    Assumes the input consists of lowercase letters a-z.
    """
    return "".join(
        chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s
    )

