def split_words(txt):
    """
    Splits input string by whitespace if present, 
    otherwise by commas if present, 
    otherwise returns count of lowercase letters with odd ASCII offset from 'a'.

    Args:
        txt (str): Input string to be processed.

    Returns:
        list or int: Split string parts or count of specific lowercase letters.
    """

    # Check for whitespace and split if present
    if any(char.isspace() for char in txt):
        return txt.split()

    # Check for commas and split if present (and no whitespace)
    elif ',' in txt:
        return txt.split(',')

    # If neither above conditions met, count lowercase letters with odd ASCII offset from 'a'
    else:
        return sum(1 for char in txt 
                   if char.islower() and (ord(char) - ord('a')) % 2!= 0)
